#!/usr/bin/env python3
"""Generate static bit-pattern ABI data for the libmvec public-ABI program.

Sources and provenance
======================
* Finite inputs are regenerated by this suite, not copied from an older
  released data set: the stream, domains and seed (123456789) match
  ``single/libmvec/generate_data.py`` exactly (64-bit LCG,
  state = state*6364136223846793005 + 1 mod 2**64,
  u = (state >> 11) / 2**53).  The ABI header samples indices
  0,16,...,1008 of that same 1024-point corpus, so the ABI and performance
  programs consume one shared oracle input stream.
* Every reference is a host MPFR 512-bit directed-interval round: the
  downward and upward endpoints must round to the same representable value
  under RNE, otherwise generation fails (no silent relaxation).
* Special values are C99/IEEE-754 / glibc-libm special cases.  Their
  references are still produced independently by MPFR (which implements
  the IEEE pow and log/exp/trig special cases).  The required/forbidden
  fflags columns are a *regression contract measured from the installed
  GLIBC_2.45 kernels* (toolchain evidence tests/t06-contract/special_table.c
  at VLEN=128: log(+-0) raises DZ, sNaN raises NV, overflow OF|NX,
  underflow UF|NX); they are recorded as observed behaviour, not offered
  as an independent IEEE/ISA proof, and are never relaxed.
* Thresholds are inherited from the released corpus controls, numbers
  unchanged: double log/exp/sin/cos/pow <= 1 ULP, logf <= 3 ULP,
  expf <= 2 ULP.

The emitted header is checked by test_abi.py and is the only oracle the
bare-metal ABI program consumes.  No host libm value is used at runtime.
"""
import argparse
import ctypes as C
import ctypes.util
import hashlib
import struct
from pathlib import Path

SEED = 123456789
CORPUS_COUNT = 1024
FINITE_PER_FUNC = 64
CORPUS_STRIDE = CORPUS_COUNT // FINITE_PER_FUNC

# Corpus controls from single/libmvec/generate_data.py -- do not relax.
LIMITS = dict(log=1, exp=1, sin=1, cos=1, pow=1, logf=3, expf=2)

NV, DZ, OF, UF, NX = 0x10, 0x08, 0x04, 0x02, 0x01
ALL = NV | DZ | OF | UF | NX
K_ULP, K_NAN, K_EXACT = 0, 1, 2

FUNCS = ('log', 'exp', 'sin', 'cos', 'pow', 'logf', 'expf')


class MPFR(C.Structure):
    _fields_ = [('prec', C.c_long), ('sign', C.c_int),
                ('exp', C.c_long), ('d', C.c_void_p)]


class Oracle:
    def __init__(self):
        name = ctypes.util.find_library('mpfr') or 'libmpfr.so.6'
        self.lib = C.CDLL(name)
        self.name = name
        p = C.POINTER(MPFR)
        for f in ('log', 'exp', 'sin', 'cos'):
            getattr(self.lib, 'mpfr_' + f).argtypes = [p, p, C.c_int]
        self.lib.mpfr_pow.argtypes = [p, p, p, C.c_int]
        self.lib.mpfr_init2.argtypes = [p, C.c_long]
        self.lib.mpfr_clear.argtypes = [p]
        self.lib.mpfr_set_d.argtypes = [p, C.c_double, C.c_int]
        self.lib.mpfr_get_d.argtypes = [p, C.c_int]
        self.lib.mpfr_get_d.restype = C.c_double
        self.lib.mpfr_get_flt.argtypes = [p, C.c_int]
        self.lib.mpfr_get_flt.restype = C.c_float
        self.lib.mpfr_get_version.restype = C.c_char_p
        self.version = self.lib.mpfr_get_version().decode()
        self.a, self.b, self.lo, self.hi = (MPFR() for _ in range(4))
        for v in (self.a, self.b, self.lo, self.hi):
            self.lib.mpfr_init2(C.byref(v), 512)

    def ref(self, func, x, y, single):
        lib = self.lib
        lib.mpfr_set_d(C.byref(self.a), x, 0)
        lib.mpfr_set_d(C.byref(self.b), y, 0)
        base = func.removesuffix('f')
        fn = getattr(lib, 'mpfr_' + base)
        for dest, rnd in ((self.lo, 3), (self.hi, 2)):  # RNDD / RNDU
            if base == 'pow':
                fn(C.byref(dest), C.byref(self.a), C.byref(self.b), rnd)
            else:
                fn(C.byref(dest), C.byref(self.a), rnd)
        get = lib.mpfr_get_flt if single else lib.mpfr_get_d
        lo = get(C.byref(self.lo), 0)
        hi = get(C.byref(self.hi), 0)
        lo_bits = bits(lo, single)
        hi_bits = bits(hi, single)
        if lo_bits != hi_bits:
            raise RuntimeError(f'ambiguous MPFR interval {func}({x!r},{y!r}): '
                               f'{lo_bits:#x}/{hi_bits:#x}')
        return lo_bits

    def close(self):
        for v in (self.a, self.b, self.lo, self.hi):
            self.lib.mpfr_clear(C.byref(v))


def bits(value, single):
    if single:
        return struct.unpack('<I', struct.pack('<f', value))[0]
    return struct.unpack('<Q', struct.pack('<d', value))[0]


def frm_bits(value, single):
    if single:
        return struct.unpack('<f', struct.pack('<I', value))[0]
    return struct.unpack('<d', struct.pack('<Q', value))[0]


D64 = dict(
    qnan=0x7ff8000000000000, snan=0x7ff0000000000001,
    pinf=0x7ff0000000000000, ninf=0xfff0000000000000,
    pzero=0x0000000000000000, nzero=0x8000000000000000,
    one=0x3ff0000000000000, two=0x4000000000000000,
    mone=0xbff0000000000000, mtwo=0xc000000000000000,
    three=0x4008000000000000, half=0x3fe0000000000000,
    mhalf=0xbfe0000000000000, thousand=0x408f400000000000,
    mthousand=0xc08f400000000000, eighth=0x3fc0000000000000,
    i2_11=0x3ff8000000000000, p1024=0x4090000000000000,
    m1075=0xc090cc0000000000, m1074=0xc090c80000000000,
    big=0x7fe0000000000000,
)
D32 = dict(
    qnan=0x7fc00000, snan=0x7f800001,
    pinf=0x7f800000, ninf=0xff800000,
    pzero=0x00000000, nzero=0x80000000,
    one=0x3f800000, two=0x40000000,
    mone=0xbf800000, mtwo=0xc0000000,
    three=0x40400000, half=0x3f000000,
    mhalf=0xbf000000, hundred=0x42c80000,
    mhundred=0xc2c80000, thousand=0x447a0000,
    mthousand=0xc47a0000, eighth=0x3e000000,
    big=0x7f000000,
)

# (label, x, y, required flags, forbidden flags, exact)
# exact=True means the interface must return the reference bit pattern
# verbatim; otherwise the corpus ULP threshold applies.
SPECIALS = {
    'log': [
        ('log(+0)', D64['pzero'], 0, DZ, NV | OF | UF | NX, True),
        ('log(-0)', D64['nzero'], 0, DZ, NV | OF | UF | NX, True),
        ('log(1)', D64['one'], 0, 0, ALL, True),
        ('log(-1)', D64['mone'], 0, NV, DZ | OF | UF, True),
        ('log(-2)', D64['mtwo'], 0, NV, DZ | OF | UF, True),
        ('log(+inf)', D64['pinf'], 0, 0, ALL, True),
        ('log(-inf)', D64['ninf'], 0, NV, DZ | OF | UF, True),
        ('log(qNaN)', D64['qnan'], 0, 0, NX | DZ | OF | UF, True),
        ('log(sNaN)', D64['snan'], 0, NV, DZ | OF | UF, True),
    ],
    'exp': [
        ('exp(0)', D64['pzero'], 0, 0, ALL, True),
        ('exp(-0)', D64['nzero'], 0, 0, ALL, True),
        ('exp(+inf)', D64['pinf'], 0, 0, ALL, True),
        ('exp(-inf)', D64['ninf'], 0, 0, ALL, True),
        ('exp(qNaN)', D64['qnan'], 0, 0, NX | DZ | OF | UF, True),
        ('exp(sNaN)', D64['snan'], 0, NV, DZ | OF | UF, True),
        ('exp(1)', D64['one'], 0, NX, NV | DZ | OF, False),
        ('exp(1000)', D64['thousand'], 0, OF | NX, NV | DZ | UF, True),
        ('exp(-1000)', D64['mthousand'], 0, UF | NX, NV | DZ | OF, True),
    ],
    'sin': [
        ('sin(+0)', D64['pzero'], 0, 0, ALL, True),
        ('sin(-0)', D64['nzero'], 0, 0, ALL, True),
        ('sin(+inf)', D64['pinf'], 0, NV, DZ | OF | UF, True),
        ('sin(-inf)', D64['ninf'], 0, NV, DZ | OF | UF, True),
        ('sin(qNaN)', D64['qnan'], 0, 0, NX | DZ | OF | UF, True),
        ('sin(sNaN)', D64['snan'], 0, NV, DZ | OF | UF, True),
    ],
    'cos': [
        ('cos(+0)', D64['pzero'], 0, 0, ALL, True),
        ('cos(-0)', D64['nzero'], 0, 0, ALL, True),
        ('cos(+inf)', D64['pinf'], 0, NV, DZ | OF | UF, True),
        ('cos(-inf)', D64['ninf'], 0, NV, DZ | OF | UF, True),
        ('cos(qNaN)', D64['qnan'], 0, 0, NX | DZ | OF | UF, True),
        ('cos(sNaN)', D64['snan'], 0, NV, DZ | OF | UF, True),
    ],
    'pow': [
        ('pow(0,0)', D64['pzero'], D64['pzero'], 0, ALL, True),
        ('pow(-0,0)', D64['nzero'], D64['pzero'], 0, ALL, True),
        ('pow(0,-1)', D64['pzero'], D64['mone'], DZ, NV | OF | UF, True),
        ('pow(-0,-1)', D64['nzero'], D64['mone'], DZ, NV | OF | UF, True),
        ('pow(-2,3)', D64['mtwo'], D64['three'], 0, ALL, True),
        ('pow(-2,2)', D64['mtwo'], D64['two'], 0, ALL, True),
        ('pow(-1,0.5)', D64['mone'], D64['half'], NV, DZ | OF | UF, True),
        ('pow(-2,0.5)', D64['mtwo'], D64['half'], NV, DZ | OF | UF, True),
        ('pow(2,1024)', D64['two'], D64['p1024'], OF | NX, NV | DZ | UF, True),
        ('pow(2,-1075)', D64['two'], D64['m1075'], UF | NX, NV | DZ | OF, True),
        ('pow(+inf,2)', D64['pinf'], D64['two'], 0, ALL, True),
        ('pow(+inf,-1)', D64['pinf'], D64['mone'], 0, ALL, True),
        ('pow(0.5,+inf)', D64['half'], D64['pinf'], 0, ALL, True),
        ('pow(2,+inf)', D64['two'], D64['pinf'], 0, ALL, True),
        ('pow(qNaN,0)', D64['qnan'], D64['pzero'], 0, ALL, True),
        ('pow(1,qNaN)', D64['one'], D64['qnan'], 0, ALL, True),
        ('pow(2,qNaN)', D64['two'], D64['qnan'], 0, NX | DZ | OF | UF, True),
        ('pow(sNaN,2)', D64['snan'], D64['two'], NV, DZ | OF | UF, True),
    ],
    'logf': [
        ('logf(+0)', D32['pzero'], 0, DZ, NV | OF | UF | NX, True),
        ('logf(-0)', D32['nzero'], 0, DZ, NV | OF | UF | NX, True),
        ('logf(1)', D32['one'], 0, 0, ALL, True),
        ('logf(-1)', D32['mone'], 0, NV, DZ | OF | UF, True),
        ('logf(-2)', D32['mtwo'], 0, NV, DZ | OF | UF, True),
        ('logf(+inf)', D32['pinf'], 0, 0, ALL, True),
        ('logf(-inf)', D32['ninf'], 0, NV, DZ | OF | UF, True),
        ('logf(qNaN)', D32['qnan'], 0, 0, NX | DZ | OF | UF, True),
        ('logf(sNaN)', D32['snan'], 0, NV, DZ | OF | UF, True),
    ],
    'expf': [
        ('expf(0)', D32['pzero'], 0, 0, ALL, True),
        ('expf(-0)', D32['nzero'], 0, 0, ALL, True),
        ('expf(+inf)', D32['pinf'], 0, 0, ALL, True),
        ('expf(-inf)', D32['ninf'], 0, 0, ALL, True),
        ('expf(qNaN)', D32['qnan'], 0, 0, NX | DZ | OF | UF, True),
        ('expf(sNaN)', D32['snan'], 0, NV, DZ | OF | UF, True),
        ('expf(1)', D32['one'], 0, NX, NV | DZ | OF, False),
        ('expf(100)', D32['hundred'], 0, OF | NX, NV | DZ | UF, True),
        ('expf(-100)', D32['mhundred'], 0, UF | NX, NV | DZ | OF, False),
        ('expf(-1000)', D32['mthousand'], 0, UF | NX, NV | DZ | OF, True),
    ],
}


def corpus_domain(func):
    base = func.removesuffix('f')
    if base in ('log', 'pow'):
        return 'x in [0.125,8), y in [-2,2)' if base == 'pow' else 'x in [0.125,8)'
    if base == 'exp':
        return 'x in [-8,8)'
    return 'x in [-32,32)'


def finite_samples(oracle, func):
    single = func.endswith('f')
    base = func.removesuffix('f')
    state = SEED
    mask = (1 << 64) - 1
    rows = []
    for i in range(CORPUS_COUNT):
        state = (state * 6364136223846793005 + 1) & mask
        u = (state >> 11) / 9007199254740992.0
        state = (state * 6364136223846793005 + 1) & mask
        v = (state >> 11) / 9007199254740992.0
        x = (0.125 + 7.875 * u) if base in ('log', 'pow') else (
            16 * u - 8 if base == 'exp' else 64 * u - 32)
        y = 4 * v - 2
        if single:
            x = struct.unpack('<f', struct.pack('<f', x))[0]
            y = struct.unpack('<f', struct.pack('<f', y))[0]
        if i % CORPUS_STRIDE == 0:
            xb, yb = bits(x, single), bits(y, single)
            rb = oracle.ref(func, x, y, single)
            rows.append((f'{func} corpus[{i}]', xb, yb, rb, 0, 0, K_ULP))
    return rows


def special_nodes(oracle, func):
    single = func.endswith('f')
    rows = []
    for label, xb, yb, req, forbid, exact in SPECIALS[func]:
        if req & forbid:
            raise RuntimeError(f'{label}: required and forbidden flags overlap')
        x = frm_bits(xb, single)
        y = frm_bits(yb, single)
        rb = oracle.ref(func, x, y, single)
        ref_double = frm_bits(rb, single)
        kind = K_NAN if ref_double != ref_double else (K_EXACT if exact else K_ULP)
        rows.append((label, xb, yb, rb, req, forbid, kind))
    return rows


def c_row(r, single):
    _, x, y, ref, req, forbid, kind = r
    wide = 'U' if single else 'ULL'
    width = 8 if single else 16
    return (f'  {{ 0x{x:0{width}x}{wide}, 0x{y:0{width}x}{wide}, '
            f'0x{ref:0{width}x}{wide}, 0x{req:02x}, 0x{forbid:02x}, {kind} }}, '
            f'/* {r[0]} */')


def emit(out_path, script_sha):
    oracle = Oracle()
    info = {}
    arrays = {}
    try:
        for func in FUNCS:
            single = func.endswith('f')
            rows = finite_samples(oracle, func) + special_nodes(oracle, func)
            if len(rows) != FINITE_PER_FUNC + len(SPECIALS[func]):
                raise RuntimeError(f'{func}: unexpected row count {len(rows)}')
            arrays[func] = (single, rows)
            info[func] = dict(count=len(rows), single=single,
                              finite=FINITE_PER_FUNC,
                              specials=len(SPECIALS[func]),
                              domain=corpus_domain(func),
                              ulp=LIMITS[func])
    finally:
        version = oracle.version
        oracle.close()

    lines = [
        '/* Generated by single/libmvec/abi-probe.py -- do not edit by hand.',
        ' *',
        ' * Oracle provenance:',
        f' *   generator      abi-probe.py sha256 {script_sha}',
        f' *   host MPFR      {version} (libmpfr, 512-bit precision)',
        f' *   seed           {SEED}',
        f' *   corpus         first {FINITE_PER_FUNC} of {CORPUS_COUNT} points per function,',
        f' *                  stride {CORPUS_STRIDE}, from this suite\'s own 64-bit LCG',
        ' *                  corpus (generate_data.py, seed 123456789,',
        ' *                  state = state*6364136223846793005+1 mod 2^64); not an',
        ' *                  older released data set -- ABI and perf share this stream',
        ' *   specials       C99/IEEE-754 log/exp/sin/cos/pow cases; references from',
        ' *                  host MPFR.  The fflags columns are a regression contract',
        ' *                  measured on the installed GLIBC_2.45 kernels (VLEN=128',
        ' *                  evidence), not an independent IEEE/ISA proof',
        ' *   thresholds     inherited released controls, values unchanged:',
        ' *                  double log/exp/sin/cos/pow 1 ULP, logf 3 ULP, expf 2 ULP',
        ' *   runtime oracle none: the bare-metal ABI program only reads this file',
        ' *',
        ' * Row layout: { x_bits, y_bits, reference_bits, required_fflags,',
        ' *               forbidden_fflags, kind } where kind 0=ULP-limited,',
        ' *               1=NaN (payload not promised), 2=exact bits.',
        ' */',
        '#ifndef ABI_DATA_H',
        '#define ABI_DATA_H',
        '#include <stdint.h>',
        '',
        f'#define ABI_DATA_SEED {SEED}u',
        f'#define ABI_DATA_CORPUS_COUNT {CORPUS_COUNT}u',
        f'#define ABI_DATA_FINITE_PER_FUNC {FINITE_PER_FUNC}u',
        f'#define ABI_DATA_MPFR_VERSION "{version}"',
        f'#define ABI_DATA_GENERATOR_SHA256 "{script_sha}"',
        '',
        '#define ABI_FE_NX 0x01u',
        '#define ABI_FE_UF 0x02u',
        '#define ABI_FE_OF 0x04u',
        '#define ABI_FE_DZ 0x08u',
        '#define ABI_FE_NV 0x10u',
        '#define ABI_FE_ALL 0x1fu',
        '',
        '#define ABI_KIND_ULP 0u',
        '#define ABI_KIND_NAN 1u',
        '#define ABI_KIND_EXACT 2u',
        '',
        'typedef struct {',
        '  uint64_t x, y, ref;',
        '  uint16_t req, forbid;',
        '  uint8_t kind;',
        '} abi_case64;',
        '',
        'typedef struct {',
        '  uint32_t x, y, ref;',
        '  uint16_t req, forbid;',
        '  uint8_t kind;',
        '} abi_case32;',
        '',
    ]
    for func in FUNCS:
        lines.append(f'#define ABI_ULP_{func.upper()} {LIMITS[func]}')
    lines.append('')
    for func in FUNCS:
        single, rows = arrays[func]
        typ = 'abi_case32' if single else 'abi_case64'
        lines.append(f'#define ABI_CASES_{func.upper()} {len(rows)}u')
        lines.append(f'static const {typ} abi_cases_{func}[ABI_CASES_{func.upper()}] = {{')
        lines.extend(c_row(r, single) for r in rows)
        lines.append('};')
        lines.append('')
    lines += ['#endif /* ABI_DATA_H */', '']
    text = '\n'.join(lines)
    Path(out_path).write_text(text)
    return info, text


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--out', type=Path, default=Path(__file__).with_name('abi-data.h'),
                        help='output header (default: abi-data.h next to this script)')
    parser.add_argument('--check', action='store_true',
                        help='regenerate in memory and fail if the checked-in header differs')
    parser.add_argument('--json', action='store_true', help='print data summary as JSON')
    args = parser.parse_args()
    script_sha = hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    out = args.out
    info, text = emit(out, script_sha)
    if args.check:
        if not out.is_file() or out.read_text() != text:
            raise SystemExit(f'{out} is stale; rerun abi-probe.py')
        print(f'{out}: up to date ({sum(v["count"] for v in info.values())} cases)')
        return 0
    if args.json:
        import json
        print(json.dumps(dict(seed=SEED, functions=info), indent=2))
    else:
        print(f'wrote {out}: ' + ', '.join(f'{k}={v["count"]}' for k, v in info.items()))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
